flags.typeql:
match
$m isa movie, has revenue $rev;
reduce $max_rev = max($rev);
match
$m2 isa movie, has revenue $rev2;
$rev2 == $max_rev;
$r isa rated (user: $u, film: $m2), has rating $rat;
$u has name $n;
sort $rat desc;
limit 3;
fetch { "name": $n, "rating": $rat };

match
$m isa movie, has title $title, has revenue $revenue, has budget $budget;
let $total = $revenue + $budget;
$total > 1000000000;
fetch {
  "title": $title,
  "revenue": $revenue,
  "budget": $budget
};

match
$d isa person;
directed (director: $d, film: $m);
not {
  directed (director: $d, film: $m2);
  $m2 has imdb_rating $r;
  $r < 6.0;
};
fetch {
  "DirectorName": $d.name
};

match
$a isa person;
acted_in (actor: $a, film: $m);
directed (director: $d1, film: $m);
directed (director: $d2, film: $m);
not { $d1 is $d2; };
select $a;
distinct;
fetch { "ActorName": $a.name };

match
$a isa person;
acted_in (actor: $a, film: $m1);
in_genre (film: $m1, genre: $g1);
$g1 isa genre, has name "Comedy";
acted_in (actor: $a, film: $m2);
in_genre (film: $m2, genre: $g2);
$g2 isa genre, has name "Drama";
limit 3;
fetch {
  "actorName": $a.name
};

with fun oldest_year() -> integer:
  match $m isa movie, has year $y;
  return min($y);
with fun newest_year() -> integer:
  match $m isa movie, has year $y;
  return max($y);
match
  $user isa user;
  let $min_year = oldest_year();
  let $max_year = newest_year();
  $old_movie isa movie, has year $oy;
  $oy == $min_year;
  $new_movie isa movie, has year $ny;
  $ny == $max_year;
  rated (user: $user, film: $old_movie);
  rated (user: $user, film: $new_movie);
limit 3;
fetch { "userName": $user.n

match
  $high isa movie, has revenue $rh;
  not { $other_high isa movie, has revenue $rh2; $rh2 > $rh; };
  $low isa movie, has revenue $rl;
  not { $other_low isa movie, has revenue $rl2; $rl2 < $rl; };
  acted_in (actor: $actor, film: $high);
  acted_in (actor: $actor, film: $low);
  $actor has name $name;
limit 3;
fetch { "actorName": $name };

with fun directed_count($p: person) -> integer:
  match directed (director: $p, film: $m);
  return count;
with fun acted_count($p: person) -> integer:
  match acted_in (actor: $p, film: $m);
  return count;
match
  $p isa person;
  directed (director: $p, film: $m);
  $m has imdb_rating $r;
  let $dc = directed_count($p);
  let $ac = acted_count($p);
  $dc <= $ac;
sort $r desc;
limit 5;
fetch { "MovieTitle": $m.title, "Rating": $r };
